import { NextResponse } from 'next/server';
import { FieldValue } from 'firebase-admin/firestore';
import { getAdminDb } from '@/lib/firebaseAdmin';
import { verifyPaystackTransaction } from '@/lib/paystack';

export const runtime = 'nodejs';

// Donation references are generated by the app; reject anything unexpected early.
const REFERENCE_PATTERN = /^[A-Za-z0-9_.-]{6,100}$/;

export async function POST(request) {
    try {
        const body = await request.json().catch(() => ({}));
        const reference = typeof body?.reference === 'string' ? body.reference.trim() : '';

        if (!reference || !REFERENCE_PATTERN.test(reference)) {
            return NextResponse.json({ success: false, message: "Invalid reference" }, { status: 400 });
        }

        // 1. Find the donation (Admin SDK: server-side, not subject to client rules)
        const adminDb = getAdminDb();
        const snapshot = await adminDb
            .collection('donations')
            .where('reference', '==', reference)
            .limit(1)
            .get();

        if (snapshot.empty) {
            return NextResponse.json({ success: false, message: "Donation record not found" }, { status: 404 });
        }

        const docSnapshot = snapshot.docs[0];
        const docRef = docSnapshot.ref;
        const donation = docSnapshot.data();

        // Already confirmed: never downgrade or re-process.
        if (donation.status === 'Success') {
            return NextResponse.json({ success: true, message: "Verified successfully" });
        }

        // 2. Verify with Paystack
        const paystackResponse = await verifyPaystackTransaction(reference);
        const pData = paystackResponse?.data;
        const pStatus = pData?.status; // 'success', 'failed', 'abandoned', or undefined

        // 3. Determine app status
        let newStatus = 'Pending';
        if (pStatus === 'success') {
            newStatus = 'Success';
        } else if (pStatus === 'failed') {
            newStatus = 'Failed';
        } else if (pStatus === 'abandoned') {
            newStatus = 'Cancelled';
        } else if (!paystackResponse?.status) {
            // Transaction not found at Paystack (e.g. user closed immediately)
            newStatus = 'Cancelled';
        }

        // 4. Integrity check: a "success" must match what the donor was asked to pay.
        let amountMismatch = false;
        if (newStatus === 'Success') {
            const expectedKobo = Math.ceil(Number(donation.amount) * 100);
            const paidKobo = Number(pData?.amount);
            const currencyOk = !pData?.currency || pData.currency === 'NGN';
            if (!Number.isFinite(expectedKobo) || expectedKobo !== paidKobo || !currencyOk) {
                amountMismatch = true;
                newStatus = 'Pending';
            }
        }

        // 5. Update database
        const updateData = {
            updatedAt: FieldValue.serverTimestamp(),
            gateway: "paystack",
        };

        if (amountMismatch) {
            updateData.flag = 'amount_mismatch';
            updateData.paystackMessage = 'Paid amount or currency did not match the donation record';
            updateData.paystackReference = pData?.reference || reference;
            updateData.paystackTransactionId = String(pData?.id ?? '');
        } else {
            updateData.status = newStatus;
            if (pData) {
                updateData.paystackReference = pData.reference;
                updateData.paystackTransactionId = String(pData.id);
                updateData.paystackChannel = pData.channel;
                if (paystackResponse.message) updateData.paystackMessage = paystackResponse.message;
                if (newStatus === 'Success') updateData.paidAt = FieldValue.serverTimestamp();
            }
        }

        if (amountMismatch || donation.status !== newStatus) {
            await docRef.update(updateData);
        }

        // 6. Response
        if (amountMismatch) {
            return NextResponse.json({ success: false, message: "Payment needs manual review" });
        }
        if (newStatus === 'Success') {
            return NextResponse.json({ success: true, message: "Verified successfully" });
        }
        return NextResponse.json({ success: false, message: `Transaction ${newStatus}` });

    } catch (error) {
        console.error("Verification API Error:", error);
        return NextResponse.json({ success: false, message: "Server error" }, { status: 500 });
    }
}
